import time
from functools import wraps

def retry(times=3, delay=0.1):
    def deco(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            last = None
            for attempt in range(1, times + 1):
                try:
                    return fn(*args, **kwargs)
                except Exception as exc:
                    last = exc
                    if attempt == times:
                        raise
                    time.sleep(delay)
            raise last
        return wrapper
    return deco

