class Node:
    def __init__(self, val, left=None, right=None):
        self.val, self.left, self.right = val, left, right

def serialize(root):
    out = []
    def walk(n):
        if n is None:
            out.append(None)
            return
        out.append(n.val)
        walk(n.left)
        walk(n.right)
    walk(root)
    return out

